content.content:
1	/**
2	 * T2.5 poll reconciliation.
3	 *
4	 * Webhooks get dropped, so polling is the safety net that makes a lost
5	 * delivery survivable. A dispatched run carries `poll_after` and the tick
6	 * advances it by re-fetching the authoritative call. Follow-up crosses tick
7	 * boundaries rather than looping, because a free Edge Function allows 150
8	 * seconds of wall clock per request.
9	 *
10	 * Whichever of the webhook and the poll arrives first wins. Every write here
11	 * is a conditional PATCH that only matches a still-pending run, so the second
12	 * arrival changes nothing and records nothing.
13	 *
14	 * This module sets a terminal `state` and deliberately leaves `completed_at`
15	 * null. The tick's finaliser owns `completed_at` and the ingestion that
16	 * follows, because `terminalRuns()` selects terminal runs with a null
17	 * `completed_at`, and a poll must not shortcut that.
18	 */
19	
20	import type { CalleDeps } from "./calle.ts";
21	import { recordCallEvent } from "./events.ts";
22	import type { CallStatus, CallTaskFixture } from "./fixtures.ts";
23	
24	/** The first follow-up is set by dispatch. Each pass after that waits ten. */
25	export const POLL_INTERVAL_MS = 10_000;
26	
27	/**
28	 * A run the provider never resolves is worse than a failed one, because it is
29	 * invisible. Give up well past the 140 seconds a real call took, and name the
30	 * reason on the run so an operator sees where it stopped.
31	 */
32	export const POLL_GIVE_UP_MS = 15 * 60_000;
33	
34	/** The terminal states the provider can report, mapped onto `call_runs.state`. */
35	export type TerminalState = "completed" | "failed" | "canceled";
36	
37	export type PollableRun = {
38	  id: string;
39	  state: string;
40	  poll_after: string | null;
41	};
42	
43	type RunRow = {
44	  id: string;
45	  state: string;
46	  calle_call_id: string | null;
47	  dispatched_at: string | null;
48	  poll_after: string | null;
49	  created_at: string;
50	};
51	
52	const PENDING_STATES = "in.(dispatched,awaiting_result)";
53	
54	function restUrl(base: string, path: string, query = ""): string {
55	  return `${base.replace(/\/+$/, "")}/rest/v1/${path}${query ? `?${query}` : ""}`;
56	}
57	
58	function serviceHeaders(key: string, prefer?: string): HeadersInit {
59	  const headers: Record<string, string> = {
60	    apikey: key,
61	    authorization: `Bearer ${key}`,
62	    "content-type": "application/json",
63	  };
64	  if (prefer) headers.prefer = prefer;
65	  return headers;
66	}
67	
68	export function terminalStateFor(status: CallStatus): TerminalState | null {
69	  if (status === "completed") return "completed";
70	  if (status === "failed") return "failed";
71	  if (status === "canceled") return "canceled";
72	  return null;
73	}
74	
75	/**
76	 * Re-fetches one authoritative call. It carries no run-state side effect, so
77	 * the tick's finaliser can reuse it for a run the webhook already terminalised.
78	 */
79	export async function fetchCall(
80	  callId: string,
81	  deps: CalleDeps,
82	): Promise<CallTaskFixture> {
83	  if (!callId) throw new Error("poll requires a CALL-E call id");
84	  const response = await deps.fetch(
85	    `${deps.calleApiBase.replace(/\/+$/, "")}/v1/calls/${encodeURIComponent(callId)}`,
86	    { headers: { authorization: `Bearer ${deps.calleApiKey}` } },
87	  );
88	  if (!response.ok) throw new Error(`CALL-E re-fetch returned HTTP ${response.status}`);
89	  const value: unknown = await response.json();
90	  if (typeof value !== "object" || value === null) {
91	    throw new Error("CALL-E re-fetch returned no call task");
92	  }
93	  const call = value as Partial<CallTaskFixture>;
94	  if (typeof call.id !== "string" || typeof call.status !== "string") {
95	    throw new Error("CALL-E re-fetch response missing id or status");
96	  }
97	  if (call.id !== callId) {
98	    throw new Error(`CALL-E re-fetch returned ${call.id} for ${callId}`);
99	  }
100	  return call as CallTaskFixture;
101	}
102	
103	async function readRun(deps: CalleDeps, runId: string): Promise<RunRow | null> {
104	  const query = new URLSearchParams({
105	    select: "id,state,calle_call_id,dispatched_at,poll_after,created_at",
106	    id: `eq.${runId}`,
107	    limit: "1",
108	  });
109	  const response = await deps.fetch(restUrl(deps.apiUrl, "call_runs", query.toString()), {
110	    headers: serviceHeaders(deps.serviceRoleKey),
111	  });
112	  if (!response.ok) throw new Error("call_runs poll read failed");
113	  const rows = await response.json() as RunRow[];
114	  return rows[0] ?? null;
115	}
116	
117	/**
118	 * Applies a patch only while the run is still pending, and reports whether
119	 * this caller was the one that won. Returning the representation is what makes
120	 * the loss observable rather than assumed.
121	 */
122	async function patchPendingRun(
123	  deps: CalleDeps,
124	  runId: string,
125	  patch: Record<string, unknown>,
126	): Promise<boolean> {
127	  const query = new URLSearchParams({ id: `eq.${runId}`, state: PENDING_STATES });
128	  const response = await deps.fetch(restUrl(deps.apiUrl, "call_runs", query.toString()), {
129	    method: "PATCH",
130	    headers: serviceHeaders(deps.serviceRoleKey, "return=representation"),
131	    body: JSON.stringify(patch),
132	  });
133	  if (!response.ok) throw new Error("call_runs poll update failed");
134	  const rows = await response.json() as unknown[];
135	  return Array.isArray(rows) && rows.length === 1;
136	}
137	
138	function failure(code: string, message: string): Record<string, string> {
139	  return { failure_code: code, failure_message: message };
140	}
141	
142	async function reschedule(
143	  deps: CalleDeps,
144	  runId: string,
145	  callId: string | null,
146	  detail: Record<string, string | number | boolean | null>,
147	): Promise<void> {
148	  const pollAfter = new Date(deps.now().getTime() + POLL_INTERVAL_MS).toISOString();
149	  const won = await patchPendingRun(deps, runId, { poll_after: pollAfter });
150	  if (!won) return;
151	  await recordCallEvent(runId, "polled", { calle_call_id: callId, ...detail }, deps);
152	}
153	
154	/**
155	 * Advances one pending run by one poll pass. A transport failure, a provider
156	 * error or an unparseable body reschedules the next pass instead of throwing,
157	 * so one poisoned run cannot fail the whole tick.
158	 */
159	export async function pollRun(run: PollableRun, deps: CalleDeps): Promise<void> {
160	  const current = await readRun(deps, run.id);
161	  // The webhook may have terminalised this run between the tick's read and
162	  // this call. That is the race, and losing it is a no-op.
163	  if (!current || current.state !== "dispatched" && current.state !== "awaiting_result") {
164	    return;
165	  }
166	
167	  if (!current.calle_call_id) {
168	    const won = await patchPendingRun(deps, run.id, {
169	      state: "failed",
170	      disposition: "not_answered",
171	      calle_failure: failure("poll_unavailable", "run has no CALL-E call id to poll"),
172	    });
173	    if (won) {
174	      await recordCallEvent(
175	        run.id,
176	        "polled",
177	        { calle_call_id: null, state: "failed", failure_reason: "run has no CALL-E call id to poll" },
178	        deps,
179	      );
180	    }
181	    return;
182	  }
183	
184	  // The window runs from a clock that never moves. `poll_after` cannot stand
185	  // in for a missing `dispatched_at`, because every pass rewrites it and the
186	  // deadline would slide forever. `created_at` is set once and never null.
187	  const windowStart = current.dispatched_at ?? current.created_at;
188	  if (windowStart) {
189	    const deadline = new Date(windowStart).getTime() + POLL_GIVE_UP_MS;
190	    if (Number.isFinite(deadline) && deps.now().getTime() > deadline) {
191	      const won = await patchPendingRun(deps, run.id, {
192	        state: "failed",
193	        disposition: "not_answered",
194	        calle_failure: failure("poll_timeout", "CALL-E never reported a terminal state"),
195	      });
196	      if (won) {
197	        await recordCallEvent(
198	          run.id,
199	          "polled",
200	          { calle_call_id: current.calle_call_id, state: "failed", failure_reason: "poll_timeout" },
201	          deps,
202	        );
203	      }
204	      return;
205	    }
206	  }
207	
208	  let call: CallTaskFixture;
209	  try {
210	    call = await fetchCall(current.calle_call_id, deps);
211	  } catch (error) {
212	    await reschedule(deps, run.id, current.calle_call_id, {
213	      state: current.state,
214	      outcome: "refetch_failed",
215	      failure_reason: error instanceof Error ? error.message : "unknown error",
216	    });
217	    return;
218	  }
219	
220	  const terminal = terminalStateFor(call.status);
221	  if (!terminal) {
222	    await reschedule(deps, run.id, call.id, { state: call.status, outcome: "pending" });
223	    return;
224	  }
225	
226	  const failureCode = call.failure_code;
227	  const patch: Record<string, unknown> = {
228	    state: terminal,
229	    calle_confidence: call.completion_confidence,
230	    calle_failure: failureCode ? failure(failureCode, call.failure_message ?? "") : null,
231	    poll_after: null,
232	  };
233	  const won = await patchPendingRun(deps, run.id, patch);
234	  if (!won) return;
235	  await recordCallEvent(
236	    run.id,
237	    "polled",
238	    { calle_call_id: call.id, state: terminal, outcome: "terminal" },
239	    deps,
240	  );
241	}
242	
243	const testFn = (Deno as { test?: (name: string, fn: () => void | Promise<void>) => void }).test;
244	if (typeof testFn === "function") {
245	  const NOW = new Date("2026-09-13T10:00:00.000Z");
246	  const RUN = "11111111-1111-4111-8111-111111111111";
247	  const CALL = "call_poll_1";
248	
249	  type Seen = { method: string; url: string; body: unknown };
250	
251	  const depsFor = (
252	    fetchImpl: typeof fetch,
253	    now: Date = NOW,
254	  ): CalleDeps => ({
255	    apiUrl: "https://orma-api.test",
256	    serviceRoleKey: "service-key",
257	    calleApiBase: "https://api.call-e.test",
258	    calleApiKey: "calle-key",
259	    webhookUrl: "https://orma-api.test/functions/v1/calle-webhook/secret",
260	    fetch: fetchImpl,
261	    now: () => now,
262	  });
263	
264	  /** Every mock branches on method and path and throws on anything else, so no
265	   * test can reach a real service and no unexpected call can pass unnoticed. */
266	  const driver = (options: {
267	    run: Partial<RunRow> & { id: string; state: string };
268	    call?: unknown;
269	    callStatus?: number;
270	    patchWins?: boolean;
271	    callThrows?: boolean;
272	  }) => {
273	    const seen: Seen[] = [];
274	    const events: { kind: string; detail: Record<string, unknown> }[] = [];
275	    const fetchImpl: typeof fetch = async (input, init) => {
276	      const request = new Request(input, init);
277	      const url = new URL(request.url);
278	      const body = init?.body ? JSON.parse(init.body as string) as Record<string, unknown> : null;
279	      seen.push({ method: request.method, url: request.url, body });
280	      if (url.host === "api.call-e.test") {
281	        if (options.callThrows) throw new Error("network down");
282	        if (options.callStatus && options.callStatus >= 400) {
283	          return new Response(null, { status: options.callStatus });
284	        }
285	        return Response.json(options.call ?? { id: CALL, status: "in_progress" });
286	      }
287	      if (url.host === "orma-api.test" && url.pathname === "/rest/v1/call_runs") {
288	        if (request.method === "GET") {
289	          return Response.json([{ calle_call_id: CALL, dispatched_at: NOW.toISOString(), poll_after: null, created_at: NOW.toISOString(), ...options.run }]);
290	        }
291	        if (request.method === "PATCH") {
292	          return Response.json(options.patchWins === false ? [] : [{ id: options.run.id }]);
293	        }
294	      }
295	      if (url.pathname === "/rest/v1/call_events" && request.method === "POST") {
296	        events.push(body as { kind: string; detail: Record<string, unknown> });
297	        return new Response(null, { status: 201 });
298	      }
299	      throw new Error(`unexpected request ${request.method} ${request.url}`);
300	    };
301	    return { seen, events, fetchImpl };
302	  };
303	
304	  testFn("a pending call reschedules the next pass instead of finalising", async () => {
305	    const { seen, events, fetchImpl } = driver({
306	      run: { id: RUN, state: "awaiting_result" },
307	      call: { id: CALL, status: "in_progress" },
308	    });
309	    await pollRun({ id: RUN, state: "awaiting_result", poll_after: null }, depsFor(fetchImpl));
310	    const patch = seen.find((entry) => entry.method === "PATCH");
311	    const body = patch?.body as { poll_after?: string; state?: string };
312	    if (!patch) throw new Error("a pending poll must persist the next poll time");
313	    if (body.state !== undefined) throw new Error("a pending poll must not write a terminal state");
314	    if (body.poll_after !== new Date(NOW.getTime() + POLL_INTERVAL_MS).toISOString()) {
315	      throw new Error("the next pass must be ten seconds out");
316	    }
317	    if (!seen.some((entry) => entry.method === "GET" && entry.url.includes("/v1/calls/" + CALL))) {
318	      throw new Error("a pending poll must re-fetch the authoritative call");
319	    }
320	    if (events.length !== 1 || events[0].kind !== "polled") {
321	      throw new Error("a pending poll must record exactly one polled event");
322	    }
323	  });
324	
325	  testFn("a completed call terminalises the run and leaves finalisation alone", async () => {
326	    const { seen, events, fetchImpl } = driver({
327	      run: { id: RUN, state: "dispatched" },
328	      call: { id: CALL, status: "completed", completion_confidence: { score: 0.9, label: "high" }, failure_code: null },
329	    });
330	    await pollRun({ id: RUN, state: "dispatched", poll_after: null }, depsFor(fetchImpl));
331	    const patch = seen.find((entry) => entry.method === "PATCH");
332	    const body = patch?.body as Record<string, unknown>;
333	    if (body.state !== "completed") throw new Error("a completed call must move the run to completed");
334	    if ("completed_at" in body) {
335	      throw new Error("the poll must not set completed_at, because the finaliser owns it");
336	    }
337	    if (!patch?.url.includes("state=in.%28dispatched%2Cawaiting_result%29")) {
338	      throw new Error("the terminal write must only match a still-pending run");
339	    }
340	    if (events[0]?.detail.state !== "completed" || events[0]?.detail.calle_call_id !== CALL) {
341	      throw new Error("the terminal event must name the provider id and the authoritative state");
342	    }
343	  });
344	
345	  testFn("a failed call records the failure the provider reported", async () => {
346	    const { events, fetchImpl } = driver({
347	      run: { id: RUN, state: "awaiting_result" },
348	      call: { id: CALL, status: "failed", failure_code: "no_answer", failure_message: "recipient did not pick up" },
349	    });
350	    await pollRun({ id: RUN, state: "awaiting_result", poll_after: null }, depsFor(fetchImpl));
351	    if (events[0]?.detail.state !== "failed") throw new Error("a failed call must move the run to failed");
352	  });
353	
354	  testFn("a run the webhook already terminalised is a no-op", async () => {
355	    const { seen, events, fetchImpl } = driver({ run: { id: RUN, state: "completed" } });
356	    await pollRun({ id: RUN, state: "completed", poll_after: null }, depsFor(fetchImpl));
357	    if (seen.some((entry) => entry.url.includes("api.call-e.test"))) {
358	      throw new Error("a terminal run must not be re-fetched");
359	    }
360	    if (seen.some((entry) => entry.method === "PATCH")) {
361	      throw new Error("a terminal run must not be written");
362	    }
363	    if (events.length !== 0) throw new Error("a terminal run must record nothing");
364	  });
365	
366	  testFn("losing the race writes nothing", async () => {
367	    const { events, fetchImpl } = driver({
368	      run: { id: RUN, state: "awaiting_result" },
369	      call: { id: CALL, status: "completed" },
370	      patchWins: false,
371	    });
372	    await pollRun({ id: RUN, state: "awaiting_result", poll_after: null }, depsFor(fetchImpl));
373	    if (events.length !== 0) {
374	      throw new Error("the loser of the race must record no timeline row");
375	    }
376	  });
377	
378	  testFn("a provider id that disagrees with the run is rejected", async () => {
379	    const { events, fetchImpl } = driver({
380	      run: { id: RUN, state: "awaiting_result" },
381	      call: { id: "call_someone_else", status: "completed" },
382	    });
383	    await pollRun({ id: RUN, state: "awaiting_result", poll_after: null }, depsFor(fetchImpl));
384	    if (events.length !== 1 || events[0].detail.outcome !== "refetch_failed") {
385	      throw new Error("a mismatched provider id must reschedule, not terminalise");
386	    }
387	  });
388	
389	  testFn("a transport failure reschedules and never throws out of the tick", async () => {
390	    const { events, fetchImpl } = driver({
391	      run: { id: RUN, state: "awaiting_result" },
392	      callThrows: true,
393	    });
394	    await pollRun({ id: RUN, state: "awaiting_result", poll_after: null }, depsFor(fetchImpl));
395	    if (events.length !== 1 || events[0].kind !== "polled" || events[0].detail.outcome !== "refetch_failed") {
396	      throw new Error("a transport failure must reschedule with a recorded reason");
397	    }
398	  });
399	
400	  testFn("a run past the give-up window is failed with a reason", async () => {
401	    const stale = { id: RUN, state: "awaiting_result", dispatched_at: new Date(NOW.getTime() - POLL_GIVE_UP_MS - 1).toISOString() };
402	    const { seen, events, fetchImpl } = driver({ run: stale });
403	    await pollRun({ id: RUN, state: "awaiting_result", poll_after: null }, depsFor(fetchImpl));
404	    const patch = seen.find((entry) => entry.method === "PATCH");
405	    const body = patch?.body as { state?: string; calle_failure?: { failure_code?: string } };
406	    if (body.state !== "failed") throw new Error("a lost call must not poll forever");
407	    if (body.calle_failure?.failure_code !== "poll_timeout") {
408	      throw new Error("giving up must name the reason on the run");
409	    }
410	    if (seen.some((entry) => entry.url.includes("api.call-e.test"))) {
411	      throw new Error("a run past its window must not re-fetch");
412	    }
413	    if (events[0]?.detail.failure_reason !== "poll_timeout") {
414	      throw new Error("the timeline must name where it stopped");
415	    }
416	  });
417	
418	  testFn("a run without dispatched_at gives up on its creation time, not its sliding poll_after", async () => {
419	    const stale = {
420	      id: RUN,
421	      state: "awaiting_result",
422	      dispatched_at: null,
423	      created_at: new Date(NOW.getTime() - POLL_GIVE_UP_MS - 1).toISOString(),
424	      // Every reschedule rewrites poll_after to just behind now, so it can never age out.
425	      poll_after: new Date(NOW.getTime() - POLL_INTERVAL_MS).toISOString(),
426	    };
427	    const { seen, events, fetchImpl } = driver({ run: stale });
428	    await pollRun({ id: RUN, state: "awaiting_result", poll_after: stale.poll_after }, depsFor(fetchImpl));
429	    const read = seen.find((entry) => entry.method === "GET" && entry.url.includes("/rest/v1/call_runs"));
430	    if (!read || !new URL(read.url).searchParams.get("select")?.split(",").includes("created_at")) {
431	      throw new Error("the poll read must select created_at to bound the window");
432	    }
433	    const patch = seen.find((entry) => entry.method === "PATCH");
434	    const body = patch?.body as { state?: string; calle_failure?: { failure_code?: string } };
435	    if (body?.state !== "failed" || body.calle_failure?.failure_code !== "poll_timeout") {
436	      throw new Error("a run with no dispatched_at must still give up once its window has passed");
437	    }
438	    if (seen.some((entry) => entry.url.includes("api.call-e.test"))) {
439	      throw new Error("a run past its window must not re-fetch");
440	    }
441	    if (events[0]?.detail.failure_reason !== "poll_timeout") {
442	      throw new Error("the timeline must name where it stopped");
443	    }
444	  });
445	
446	  testFn("a run without a provider id is failed rather than polled forever", async () => {
447	    const { seen, events, fetchImpl } = driver({
448	      run: { id: RUN, state: "awaiting_result", calle_call_id: null },
449	    });
450	    await pollRun({ id: RUN, state: "awaiting_result", poll_after: null }, depsFor(fetchImpl));
451	    if (seen.some((entry) => entry.url.includes("api.call-e.test"))) {
452	      throw new Error("a run without a provider id cannot be polled");
453	    }
454	    if (events[0]?.detail.failure_reason !== "run has no CALL-E call id to poll") {
455	      throw new Error("the absence of a provider id must be visible on the timeline");
456	    }
